def finding(item, ordinal, refs):
    fid, name, primary = item
    low = name.lower()
    kinds = [primary, KINDS[(ordinal + 7) % len(KINDS)], KINDS[(ordinal + 16) % len(KINDS)]]
    return {"id": fid, "name": name,
            "description": f"Records {low} as source-qualified fulfilment context while order, party, product, inventory, shipment, service, entitlement, invoice, payment, return and records masters remain independently identifiable.",
            "source_refs": refs,
            "questions": [
                {"id": f"{fid}-q01", "text": f"What stable fulfilment, version, obligation, unit, item, party and external-master identities plus explicit profile and unknown state establish {low}?", "kind": kinds[0], "answer_data": ["fulfilment, version, order obligation, unit, item, party and external identifiers", "goods, service, digital, pickup, installation, partial, staged or third-party profile and schema version", "unknown, planned, ready, partial, completed, failed, disputed and not-applicable states"]},
                {"id": f"{fid}-q02", "text": f"Who promises, supplies, prepares, dispatches, carries, hands over, receives, inspects, accepts, corrects or may rely on {low}, for which purpose and under what authority?", "kind": kinds[1], "answer_data": ["buyer, seller, supplier, provider, delivery party, recipient, beneficiary, agent, carrier, inspector and source system", "purpose, contract, order, delegation, terms, policy, access, confidentiality, retention and jurisdiction", "conflict, exception, segregation of duties, notice, escalation and accountability"]},
                {"id": f"{fid}-q03", "text": f"Which requested, promised, planned, ready, dispatched, arrived, attempted, handed-over, received, inspected, accepted, completed, observed, ingested and known times, sources and evidence qualify {low}?", "kind": kinds[2], "answer_data": ["distinct obligation, readiness, dispatch, transport, handover, receipt, inspection, acceptance, completion and knowledge times", "order, inventory, dispatch, shipment, service, receipt, inspection, invoice, evidence, quality and uncertainty references", "timezone, quantity variance, correction, successor, dispute, legal hold, projection loss and audit"]}],
            "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed fulfilment data for {low}, qualified by version, obligation, authority, quantity, time, condition, uncertainty and provenance.", "value_kind": "collection", "cardinality": "0..n", "required": False, "source_refs": refs}],
            "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or successor-versioned fulfilment evidence for {low}.", "media_or_form": ["logical fulfilment specification assertion", "obligation, unit, dispatch, handover, receipt, inspection, exception, completion, validation or projection record"], "serial": True, "identity_strategy": f"Fulfilment ID plus independent version, obligation, unit, dispatch, receipt or event ID and artifact kind for {fid}; party, order number, date, location, filename or digest never identifies fulfilment alone.", "source_refs": refs}],
            "inline_only_rationale": None}


def structure():
    bundles, ordinal = [], 0
    for bid, bname, rationale, layers in ROWS:
        rendered = []
        for lid, lname, refs, items in layers:
            fs = []
            for item in items:
                ordinal += 1
                fs.append(finding(item, ordinal, refs))
            rendered.append({"id": lid, "name": lname, "description": f"Groups source-qualified fulfilment context for {lname.lower()}.", "source_refs": refs, "findings": fs})
        bundles.append({"id": bid, "name": bname, "description": f"Groups fulfilment context for {bname.lower()}.", "rationale": rationale, "source_refs": sorted({r for layer in rendered for r in layer["source_refs"]}), "layers": rendered})
    return {"bundles": bundles}


